// ClusterServiceClient is a client for the hotbed.v1.ClusterService service.
type ClusterServiceClient interface {
	// Join admits the calling tailnet node as a worker.
	Join(context.Context, *v1.JoinRequest) (*v1.JoinResponse, error)
	// PushEvents delivers a worker's events, in order, from after what the
	// controller has applied; or a checkpoint of its state when the
	// controller cannot continue from what it has.
	PushEvents(context.Context, *v1.PushEventsRequest) (*v1.PushEventsResponse, error)
	// Heartbeat is a worker's live usage, lossy: the latest wins. It keeps
	// the node online, and its reply is what the worker should host.
	Heartbeat(context.Context, *v1.HeartbeatRequest) (*v1.HeartbeatResponse, error)
	// Standby is how a worker's host powers it as the controller says: the
	// host that runs a worker in a VM (hotbed worker supervise) holds it open,
	// and the controller says whether the VM should run, at once and whenever
	// that changes. A node whose host holds it open sleeps once it has had no
	// work for its sleep_after, and wakes when a run is placed on it. It ends
	// after at most two minutes, and the host calls again with how the VM is
	// then, as it does each time it has started or stopped the VM.
	Standby(context.Context, *v1.StandbyRequest) (ClusterServiceStandbyClientStream, error)
	// ReportHostUsage reports host-side truth about a VM worker (VM CPU,
	// host CPU/load, host memory pressure) from its host supervisor so
	// controller placement, worker admission, and the cockpit can see host
	// starvation that the Linux guest cannot observe from inside its VM.
	ReportHostUsage(context.Context, *v1.ReportHostUsageRequest) (*v1.ReportHostUsageResponse, error)
	// List the cluster's workers.
	ListNodes(context.Context, *v1.ListNodesRequest) (*v1.ListNodesResponse, error)
	// GetBuild is the build the controller runs, for a platform: what a node
	// or client on it installs to run the controller's build.
	GetBuild(context.Context, *v1.GetBuildRequest) (*v1.Build, error)
	// List repos registered with the cluster.
	ListRepos(context.Context, *v1.ListReposRequest) (*v1.ListReposResponse, error)
	// Add or update a repo; its project's workspaces check it out at /work/<name>.
	// Give the project setup steps with hotbed step set.
	PutRepo(context.Context, *v1.PutRepoRequest) (*v1.Repo, error)
	// Remove a repo; workers delete its bases once no workspace uses them.
	DeleteRepo(context.Context, *v1.DeleteRepoRequest) (*v1.DeleteRepoResponse, error)
	// Build the project's next base from nothing on every worker. Bases are
	// otherwise built incrementally: each generation forks the one before,
	// pulls, and runs the steps that need to run.
	RebuildProject(context.Context, *v1.RebuildProjectRequest) (*v1.Project, error)
	// Say which nodes keep the project's bases; none for every worker.
	SetProjectHosts(context.Context, *v1.SetProjectHostsRequest) (*v1.Project, error)
	// PutStep adds a setup step to a project, or replaces the one of that
	// name. The project's next workspace gets a base that has run it.
	PutStep(context.Context, *v1.PutStepRequest) (*v1.Project, error)
	DeleteStep(context.Context, *v1.DeleteStepRequest) (*v1.Project, error)
	// ListSteps is a project's steps and, for each, whether each node's
	// newest base has run it.
	ListSteps(context.Context, *v1.ListStepsRequest) (*v1.ListStepsResponse, error)
	// Make a project, or add repos to one. Its workspaces check each repo out
	// at /work/<repo>. A repo no project holds is a project of its own name,
	// made when a session first starts in it. A repo another project holds
	// needs --shared.
	AddProject(context.Context, *v1.AddProjectRequest) (*v1.Project, error)
	// Take repos out of a project; sessions already in it stay.
	RemoveProjectRepos(context.Context, *v1.RemoveProjectReposRequest) (*v1.Project, error)
	// List the projects, the repos each holds and their setup steps.
	ListProjects(context.Context, *v1.ListProjectsRequest) (*v1.ListProjectsResponse, error)
	// A project, with every change made to it: who made it, and who added or
	// took out each repo, when.
	GetProject(context.Context, *v1.GetProjectRequest) (*v1.Project, error)
	// List every node's bases for a project (or every project when none is
	// named), newest generation first per node.
	ListBases(context.Context, *v1.ListBasesRequest) (*v1.ListBasesResponse, error)
	// List active and historical base freshens with phase/step timing summaries,
	// cold-build reasons, queue waits, and waiting workspaces.
	ListFreshens(context.Context, *v1.ListFreshensRequest) (*v1.ListFreshensResponse, error)
	// Inspect one base freshen in detail: phase and step breakdown, cold reason,
	// memory guarantee vs peak, waiting workspaces, timeline, and node admission.
	GetFreshen(context.Context, *v1.GetFreshenRequest) (*v1.GetFreshenResponse, error)
	// Everything the cockpit shows: nodes, repos, bases, workspaces, commands,
	// sessions, schedules, events and history.
	GetSnapshot(context.Context, *v1.GetSnapshotRequest) (*v1.Snapshot, error)
	// GetCommandDiagnostics is the diagnostics taken of a command as someone
	// stopped or paused it (StopCommand, PauseCommand with diagnose), oldest
	// first, live or long ended: the controller keeps them.
	GetCommandDiagnostics(context.Context, *v1.GetCommandDiagnosticsRequest) (*v1.GetCommandDiagnosticsResponse, error)
	// SaveCommandDiagnostics delivers a command's captured intervention
	// diagnostics from its worker to the controller with explicit
	// acknowledgement, independent of the event-stream checkpoint path.
	SaveCommandDiagnostics(context.Context, *v1.SaveCommandDiagnosticsRequest) (*v1.SaveCommandDiagnosticsResponse, error)
	// A node with how it decides whether to start new work (its admission:
	// whether it holds work, why, and every signal it weighs against its
	// limit), the work it recently held or made wait, and the placements
	// that weighed it.
	GetNode(context.Context, *v1.GetNodeRequest) (*v1.NodeDetail, error)
	// Retire a node that is gone for good (its machine or VM deleted): it no
	// longer shows in hotbed nodes or the cockpit and takes no runs, while
	// its history (commands, events, placements) stays. Its sessions' runs go
	// elsewhere. Refused while it is online. A worker joining again with the
	// same tailnet identity is a node again.
	RetireNode(context.Context, *v1.RetireNodeRequest) (*v1.Node, error)
	// Placement decisions, newest first: each candidate node with its cost
	// in parts, or why it was ruled out, and the node chosen. Kept a day.
	ListPlacements(context.Context, *v1.ListPlacementsRequest) (*v1.ListPlacementsResponse, error)
	// The cluster's events, newest first: what workers did (admitted, held,
	// made wait, resumed, parked, forked, ...), narrowed by node and kind.
	ListEvents(context.Context, *v1.ListEventsRequest) (*v1.ListEventsResponse, error)
	// Read organization-scoped default and per-node worker/VM/freshen configuration.
	GetWorkerConfig(context.Context, *v1.GetWorkerConfigRequest) (*v1.GetWorkerConfigResponse, error)
	// Set (merge or replace) organization default or per-node configuration
	// (org admins only). Pass WorkerConfig JSON on stdin or --file.
	SetWorkerConfig(context.Context, *v1.SetWorkerConfigRequest) (*v1.WorkerConfig, error)
	// Remove organization-scoped configuration overrides for a node (or
	// organization defaults with --defaults). Org admins only.
	DeleteWorkerConfig(context.Context, *v1.DeleteWorkerConfigRequest) (*v1.DeleteWorkerConfigResponse, error)
	// Explicitly upgrade host cladefs components (cladefsd, firecracker, guest
	// kernel) on one node or rolling across all online nodes one at a time.
	// Stages and SHA-256-verifies artifacts before draining the node, stopping
	// active commands/shells, releasing active cladefs/VM workspaces, installing
	// binaries atomically, restarting cladefsd, and verifying health.
	UpgradeSystem(context.Context, *v1.UpgradeSystemRequest) (*v1.UpgradeSystemResponse, error)
}

// NewClusterServiceClient constructs a client for the hotbed.v1.ClusterService service. Multiple
// service clients may share a single connect.Client.
func NewClusterServiceClient(client *connect.Client) ClusterServiceClient {
	return &clusterServiceClient{client: client}
}

// ClusterServiceStandbyClientStream is the client stream for the ClusterService's Standby RPC.
type ClusterServiceStandbyClientStream struct {
	stream connect.ClientStream
}

// Receive returns the next response message from the server.
func (s ClusterServiceStandbyClientStream) Receive() (*v1.StandbyResponse, error) {
	var res v1.StandbyResponse
	if err := s.stream.Receive(&res); err != nil {
		return nil, err
	}
	return &res, nil
}

// Close releases the stream's resources. It is idempotent and is typically deferred to clean up a
// stream abandoned before io.EOF.
func (s ClusterServiceStandbyClientStream) Close() error {
	return s.stream.Close()
}

