// RegisterClusterServiceHandler registers svc as the hotbed.v1.ClusterService implementation on
// server.
func RegisterClusterServiceHandler(server *connect.Server, svc ClusterServiceHandler) {
	adapter := clusterServiceHandler{svc: svc}
	server.Register(
		connect.Method{Spec: clusterServiceJoinSpec(), Handler: adapter.join},
		connect.Method{Spec: clusterServicePushEventsSpec(), Handler: adapter.pushEvents},
		connect.Method{Spec: clusterServiceHeartbeatSpec(), Handler: adapter.heartbeat},
		connect.Method{Spec: clusterServiceStandbySpec(), Handler: adapter.standby},
		connect.Method{Spec: clusterServiceReportHostUsageSpec(), Handler: adapter.reportHostUsage},
		connect.Method{Spec: clusterServiceListNodesSpec(), Handler: adapter.listNodes},
		connect.Method{Spec: clusterServiceGetBuildSpec(), Handler: adapter.getBuild},
		connect.Method{Spec: clusterServiceListReposSpec(), Handler: adapter.listRepos},
		connect.Method{Spec: clusterServicePutRepoSpec(), Handler: adapter.putRepo},
		connect.Method{Spec: clusterServiceDeleteRepoSpec(), Handler: adapter.deleteRepo},
		connect.Method{Spec: clusterServiceRebuildProjectSpec(), Handler: adapter.rebuildProject},
		connect.Method{Spec: clusterServiceSetProjectHostsSpec(), Handler: adapter.setProjectHosts},
		connect.Method{Spec: clusterServicePutStepSpec(), Handler: adapter.putStep},
		connect.Method{Spec: clusterServiceDeleteStepSpec(), Handler: adapter.deleteStep},
		connect.Method{Spec: clusterServiceListStepsSpec(), Handler: adapter.listSteps},
		connect.Method{Spec: clusterServiceAddProjectSpec(), Handler: adapter.addProject},
		connect.Method{Spec: clusterServiceRemoveProjectReposSpec(), Handler: adapter.removeProjectRepos},
		connect.Method{Spec: clusterServiceListProjectsSpec(), Handler: adapter.listProjects},
		connect.Method{Spec: clusterServiceGetProjectSpec(), Handler: adapter.getProject},
		connect.Method{Spec: clusterServiceListBasesSpec(), Handler: adapter.listBases},
		connect.Method{Spec: clusterServiceListFreshensSpec(), Handler: adapter.listFreshens},
		connect.Method{Spec: clusterServiceGetFreshenSpec(), Handler: adapter.getFreshen},
		connect.Method{Spec: clusterServiceGetSnapshotSpec(), Handler: adapter.getSnapshot},
		connect.Method{Spec: clusterServiceGetCommandDiagnosticsSpec(), Handler: adapter.getCommandDiagnostics},
		connect.Method{Spec: clusterServiceSaveCommandDiagnosticsSpec(), Handler: adapter.saveCommandDiagnostics},
		connect.Method{Spec: clusterServiceGetNodeSpec(), Handler: adapter.getNode},
		connect.Method{Spec: clusterServiceRetireNodeSpec(), Handler: adapter.retireNode},
		connect.Method{Spec: clusterServiceListPlacementsSpec(), Handler: adapter.listPlacements},
		connect.Method{Spec: clusterServiceListEventsSpec(), Handler: adapter.listEvents},
		connect.Method{Spec: clusterServiceGetWorkerConfigSpec(), Handler: adapter.getWorkerConfig},
		connect.Method{Spec: clusterServiceSetWorkerConfigSpec(), Handler: adapter.setWorkerConfig},
		connect.Method{Spec: clusterServiceDeleteWorkerConfigSpec(), Handler: adapter.deleteWorkerConfig},
		connect.Method{Spec: clusterServiceUpgradeSystemSpec(), Handler: adapter.upgradeSystem},
	)
}

