// SessionServiceClient is a client for the hotbed.v1.SessionService service.
type SessionServiceClient interface {
	// StartSession starts a session in a project: the one named, or else the
	// one project that holds the caller's checkout's repo. A repo no project
	// holds is a project of its own, made for it.
	StartSession(context.Context, *v1.StartSessionRequest) (*v1.Session, error)
	// GetSession returns a session (live or ended) with its workspaces and
	// commands, without resetting its idle timer.
	GetSession(context.Context, *v1.GetSessionRequest) (*v1.GetSessionResponse, error)
	// ListSessions lists a project's sessions, or every project's: those
	// live, and with ended, those that ended in the last day too; the most
	// recently active first.
	ListSessions(context.Context, *v1.ListSessionsRequest) (*v1.ListSessionsResponse, error)
	// SearchSessions searches persistently for sessions associated with a T3 Code
	// thread ID across every project (or one named), including ended sessions of
	// any age unless live_only is set; live sessions come first, then the most
	// recently active.
	SearchSessions(context.Context, *v1.SearchSessionsRequest) (*v1.SearchSessionsResponse, error)
	// EndSession stops the session's commands and releases its workspaces.
	// A session nothing touches for an hour ends the same way; WatchSession
	// keeps it alive.
	EndSession(context.Context, *v1.EndSessionRequest) (*v1.Session, error)
	// WatchSession streams the session's events after a cursor: first how it
	// stands, then each new batch of events as it happens. It ends when the
	// session does, or after at most two minutes, so an agent that wants the
	// session kept has to keep watching it.
	WatchSession(context.Context, *v1.WatchSessionRequest) (SessionServiceWatchSessionClientStream, error)
	// Wait, two minutes at most, for what happens in the session: its
	// commands admitted, parked, paused or ended, its workspaces ready or
	// failed, the user's answers to its questions, its reviews' ends and
	// responses, and decisions on its proposed memories. Returns the events
	// after the cursor at once if there are any. The client keeps where this
	// machine's last poll of the session left off, so each event comes once.
	// Nothing after two minutes: nothing happened yet; poll again.
	Poll(context.Context, *v1.PollRequest) (*v1.SessionEvents, error)
}

// NewSessionServiceClient constructs a client for the hotbed.v1.SessionService service. Multiple
// service clients may share a single connect.Client.
func NewSessionServiceClient(client *connect.Client) SessionServiceClient {
	return &sessionServiceClient{client: client}
}

