// WorkspaceServiceClient is a client for the hotbed.v1.WorkspaceService service.
type WorkspaceServiceClient interface {
	CreateWorkspace(context.Context, *v1.CreateWorkspaceRequest) (*v1.Workspace, error)
	GetWorkspace(context.Context, *v1.GetWorkspaceRequest) (*v1.Workspace, error)
	// WatchWorkspace streams the workspace as it is, then again each time it
	// changes (such as from preparing to ready), until it is released or the
	// caller stops listening.
	WatchWorkspace(context.Context, *v1.WatchWorkspaceRequest) (WorkspaceServiceWatchWorkspaceClientStream, error)
	ListWorkspaces(context.Context, *v1.ListWorkspacesRequest) (*v1.ListWorkspacesResponse, error)
	ReleaseWorkspace(context.Context, *v1.ReleaseWorkspaceRequest) (*v1.ReleaseWorkspaceResponse, error)
	// Sync checks out an agent's worktree in a workspace. The first message
	// names the snapshot; the rest carry a git bundle of it.
	Sync(context.Context) (WorkspaceServiceSyncClientStream, error)
	ListFiles(context.Context, *v1.ListFilesRequest) (*v1.ListFilesResponse, error)
	GetFile(context.Context, *v1.GetFileRequest) (*v1.FileContent, error)
	RunCommand(context.Context, *v1.RunCommandRequest) (*v1.Command, error)
	// OpenShell issues a single-use, short-lived SSH ticket for an interactive
	// shell (or command) in a workspace on this worker.
	OpenShell(context.Context, *v1.OpenShellRequest) (*v1.OpenShellResponse, error)
	GetCommand(context.Context, *v1.GetCommandRequest) (*v1.Command, error)
	// List a session's commands, live and just ended (-p for a project, --all
	// for every session, -e for 30-day history).
	ListCommands(context.Context, *v1.ListCommandsRequest) (*v1.ListCommandsResponse, error)
	// StopCommand ends a command: a queued one never starts, a started one is
	// stopped. With diagnose, what it is doing is taken first, and kept
	// (GetCommandDiagnostics); the agent waiting on it is told who stopped it,
	// the comment, and how to read them.
	StopCommand(context.Context, *v1.StopCommandRequest) (*v1.Command, error)
	// PauseCommand freezes a started command, its memory to swap, as a soft
	// time limit would, with diagnostics and a comment as StopCommand takes;
	// the agent waiting on it is told so. It stays paused, an agent waiting on
	// it again or not, until ResumeCommand, or its hard time limit stops it.
	PauseCommand(context.Context, *v1.PauseCommandRequest) (*v1.Command, error)
	// ResumeCommand thaws a paused command, whatever paused it. It is left to
	// its limits, as a detached one is: its soft limit counts from now.
	ResumeCommand(context.Context, *v1.ResumeCommandRequest) (*v1.Command, error)
	// FollowLog streams a command's output from an offset; with follow, until
	// the command ends or is paused. An attached command stops when no one
	// follows it.
	FollowLog(context.Context, *v1.FollowLogRequest) (WorkspaceServiceFollowLogClientStream, error)
	// GetLogLines returns the last lines of a command's output, at most
	// 1 MiB of them: FollowLog streams more.
	GetLogLines(context.Context, *v1.GetLogLinesRequest) (*v1.CommandLog, error)
	// InspectCommand takes an opt-in, non-intrusive Linux snapshot of a live
	// command's cgroup (processes, open files/sockets, cgroup stats, kernel
	// stacks, memory maps, limits) and reports which tracing tools exist on the node.
	InspectCommand(context.Context, *v1.InspectCommandRequest) (*v1.InspectCommandResponse, error)
	// TraceCommand runs an opt-in, time-bounded active Linux trace on a live
	// command (strace, perf CPU profile, perf stat, thread stack dump, or
	// curated bpftrace probe) and streams progress and results until complete or cancelled.
	TraceCommand(context.Context, *v1.TraceCommandRequest) (WorkspaceServiceTraceCommandClientStream, error)
	// SampleCommand takes a unified Activity Monitor-style Linux activity sample
	// of a live command (or one PID in its cgroup): multi-snapshot user & kernel
	// thread stacks, active syscalls with FD resolution, CPU/IO/schedstat &
	// context-switch deltas, open files/sockets (with TX/RX queues, pipe peers,
	// epoll targets, and /proc/locks), cgroup v2 & PSI stall deltas, hardware
	// performance counters, and an on-CPU eBPF profile window.
	SampleCommand(context.Context, *v1.SampleCommandRequest) (WorkspaceServiceSampleCommandClientStream, error)
	// GetProfile queries the always-on OpenTelemetry eBPF continuous profile,
	// either for a single command (command_id, live on its worker or persisted
	// after it ended) or across all processes on a node (node).
	GetProfile(context.Context, *v1.GetProfileRequest) (*v1.CommandProfile, error)
	// GetDaemonLogs returns recent WARN and ERROR slog records from the
	// controller, a worker, or all of them, newest first.
	GetDaemonLogs(context.Context, *v1.GetDaemonLogsRequest) (*v1.GetDaemonLogsResponse, error)
	// UpgradeSystem executes an explicit disruptive host cladefs/system upgrade
	// on this worker. Called only by the controller on behalf of ClusterService.UpgradeSystem.
	UpgradeSystem(context.Context, *v1.WorkerUpgradeSystemRequest) (*v1.NodeSystemUpgrade, error)
}

