// QuestionServiceClient is a client for the hotbed.v1.QuestionService service.
type QuestionServiceClient interface {
	// Ask the user: AskUserQuestion's JSON ({"questions": [...]}) on stdin
	// or --file. Each question is an entry of its own, at the top of the
	// user's order, on the list of the session's project, which its sessions
	// share; carry on with your best guess and read the answer later. With
	// --answered, record decisions already taken instead: each question is
	// answered with its implemented options and handled at once, for the user
	// to reopen if they disagree.
	AddQuestions(context.Context, *v1.AddQuestionsRequest) (*v1.AddQuestionsResponse, error)
	// Rewrite an open question: one question's JSON on stdin or --file, bare
	// or as add takes it.
	EditQuestion(context.Context, *v1.EditQuestionRequest) (*v1.Question, error)
	// Delete a question that is no longer needed, whichever session asked
	// it; it stays in the history.
	DeleteQuestion(context.Context, *v1.DeleteQuestionRequest) (*v1.Question, error)
	// A project's questions, every session's (every state but deleted),
	// newest first unless asked for another order.
	ListQuestions(context.Context, *v1.ListQuestionsRequest) (*v1.ListQuestionsResponse, error)
	// Every project with questions: how many wait on the user, and on
	// agents.
	ListQuestionProjects(context.Context, *v1.ListQuestionProjectsRequest) (*v1.ListQuestionProjectsResponse, error)
	// A question with every change made to it: what, when, and by which
	// session.
	GetQuestion(context.Context, *v1.GetQuestionRequest) (*v1.Question, error)
	// Answer a question for the user, which puts it in the outbox; or change
	// the answer of one in the outbox. The user answers in the cockpit; an
	// agent uses this only to pass on what the user said.
	AnswerQuestion(context.Context, *v1.AnswerQuestionRequest) (*v1.Question, error)
	// Dismiss a question for the user, open or answered in the outbox: it
	// will get no answer. It goes to the outbox too, so its asker learns as
	// much.
	DismissQuestion(context.Context, *v1.DismissQuestionRequest) (*v1.Question, error)
	// Rewrite a question for the user, in any state but deleted: the user
	// does this in the cockpit; an agent only to pass on the user's words.
	// An answer it has must still pick among its options. One question's
	// JSON on stdin or --file, as question edit takes it.
	ReviseQuestion(context.Context, *v1.ReviseQuestionRequest) (*v1.Question, error)
	// Return an answered, dismissed or handled question to the user, open
	// again at the top of their order, its answer cleared: the user does
	// this in the cockpit; an agent only when the user asks.
	ReopenQuestion(context.Context, *v1.ReopenQuestionRequest) (*v1.Question, error)
	// Move an open question in the user's order.
	MoveQuestion(context.Context, *v1.MoveQuestionRequest) (*v1.Question, error)
	// Acknowledge answers you have read and acted on: they leave the outbox,
	// handled; all of them or, if one is not in the outbox, none.
	AckQuestions(context.Context, *v1.AckQuestionsRequest) (*v1.AckQuestionsResponse, error)
}

// NewQuestionServiceClient constructs a client for the hotbed.v1.QuestionService service. Multiple
// service clients may share a single connect.Client.
func NewQuestionServiceClient(client *connect.Client) QuestionServiceClient {
	return &questionServiceClient{client: client}
}

