// GitAuthServiceClient is a client for the hotbed.v1.GitAuthService service.
type GitAuthServiceClient interface {
	// Start a GitHub OAuth Device Flow on the controller and return the one-time
	// user code and verification URL (use with `hotbed auth login --login-id`,
	// or run `hotbed auth login` directly for the interactive flow).
	StartGitHubLogin(context.Context, *v1.StartGitHubLoginRequest) (*v1.GitHubLoginChallenge, error)
	// Log in to GitHub on the controller via OAuth Device Flow (like `gh auth
	// login`) and store the resulting user token centrally for all workers,
	// sessions, and commands.
	CompleteGitHubLogin(context.Context, *v1.CompleteGitHubLoginRequest) (*v1.GitCredential, error)
	// Add or replace a centralized git token on the controller (for headless or
	// CI setup; prefer `hotbed auth login` for interactive OAuth login). Secrets
	// are stored write-only on the controller and never returned by list calls.
	PutGitCredential(context.Context, *v1.PutGitCredentialRequest) (*v1.GitCredential, error)
	// List centralized git credentials configured on the controller (metadata
	// only; secrets are never returned).
	ListGitCredentials(context.Context, *v1.ListGitCredentialsRequest) (*v1.ListGitCredentialsResponse, error)
	// Delete a centralized git credential from the controller.
	DeleteGitCredential(context.Context, *v1.DeleteGitCredentialRequest) (*v1.DeleteGitCredentialResponse, error)
	// Mint a short-lived git access token for a repository URL or canonical
	// remote (e.g. https://github.com/semistrict/hotbed.git), refreshing an
	// expiring OAuth token automatically when needed.
	MintGitToken(context.Context, *v1.MintGitTokenRequest) (*v1.GitToken, error)
	// Proxy a GitHub REST or GraphQL API request through the controller using
	// its stored credentials so worker commands (`gh`) never need raw tokens.
	ProxyGitHubAPI(context.Context, *v1.ProxyGitHubAPIRequest) (*v1.ProxyGitHubAPIResponse, error)
}

